@startuml

class SmartHome {
  + PhysicalAddress : string
}

class Room {
  + Name : string
}

abstract class Device {
  + DeviceIdentifier : string
}

class Sensor extends Device {
  + Type : string
}

class Actuator extends Device {
  + Type : string
}

class SensorReading {
  + MeasuredValue : string
  + Timestamp : datetime
}

class ControlCommand {
  + CommandName : string
  + Timestamp : datetime
  + Status : string
}

class ActivityLog {
  + LogEntry : string
}

class User {
  + Name : string
}

class AutomationRule {
  + Precondition : string
  + Action : string
  + IsActivated : boolean
  + LastTriggered : datetime
  + Edit() : void
  + Activate() : void
  + Deactivate() : void
}

SmartHome "1" *-- "1..*" Room
Room "1" *-- "0..*" Device
Room "1" -- "0..*" Sensor
Room "1" -- "0..*" Actuator
Sensor "1" -- "0..*" SensorReading
Actuator "1" -- "0..*" ControlCommand
SmartHome "1" *-- "0..*" ActivityLog
ActivityLog "1" -- "0..*" SensorReading
ActivityLog "1" -- "0..*" ControlCommand
User "1" -- "0..*" AutomationRule : manages
AutomationRule "0..*" -- "0..*" AutomationRule : depends on/conflicts with

@enduml

